#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char* commonPrefix(const char* x, const char* y) {
    size_t i = 0;
    while (x[i] != '\0' && y[i] != '\0' && x[i] == y[i]) {
        i++;
    }
    char* result = malloc(i + 1);
    if (result == NULL) {
        return NULL;
    }
    strncpy(result, x, i);
    result[i] = '\0';
    return result;
}

int main() {
    const char* tests[][2] = {
        {"hello", "hell"},
        {"abc", "abc"},
        {"abc", "def"},
        {"", "hello"},
        {"prefix", "pre"},
        {"a", "ab"},
        {"ab", "a"},
        {"same", "same"},
        {"", ""},
        {"longprefix", "longpref"}
    };
    int num_tests = sizeof(tests) / sizeof(tests[0]);

    for (int i = 0; i < num_tests; i++) {
        char* result = commonPrefix(tests[i][0], tests[i][1]);
        printf("Test %d: commonPrefix(\"%s\", \"%s\") = \"%s\"\n", 
               i + 1, tests[i][0], tests[i][1], result);
        free(result);
    }

    return 0;
}

