public class Solution {
    public static String commonPrefix(String x, String y) {
        int n = x.length();
        int m = y.length();
        int i = 0;
        while (i < n && i < m && x.charAt(i) == y.charAt(i)) {
            i++;
        }
        return x.substring(0, i);
    }

    public static void main(String[] args) {
        System.out.println(commonPrefix("hello", "hell"));
        System.out.println(commonPrefix("abc", "abc"));
        System.out.println(commonPrefix("abc", "def"));
        System.out.println(commonPrefix("", "test"));
        System.out.println(commonPrefix("prefix", "pre"));
    }
}
